import{_ as e,o,c as r,ae as a}from"./chunks/framework.EHGTsUvI.js";const p=JSON.parse('{"title":"Animal Food Factory","description":"","frontmatter":{},"headers":[],"relativePath":"Main/Main/GeneralKnowledge/Factorys&Utilities/Factories/animalfood.md","filePath":"Main/Main/GeneralKnowledge/Factorys&Utilities/Factories/animalfood.md"}'),i={name:"Main/Main/GeneralKnowledge/Factorys&Utilities/Factories/animalfood.md"};function n(l,t,d,s,h,c){return o(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="animal-food-factory" tabindex="-1">Animal Food Factory <a class="header-anchor" href="#animal-food-factory" aria-label="Permalink to &quot;Animal Food Factory&quot;">​</a></h1><p>The <strong>Animal Food Factory</strong> is used to convert crops into <strong>Animal Food</strong>, which can then be used to feed animals around your farm.</p><h2 id="factory-information" tabindex="-1">Factory Information <a class="header-anchor" href="#factory-information" aria-label="Permalink to &quot;Factory Information&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Information</th><th>Details</th></tr></thead><tbody><tr><td><strong>Purchase price</strong></td><td>40,000 Coins</td></tr><tr><td><strong>Storage capacity</strong></td><td>600 Crops</td></tr><tr><td><strong>Factory size</strong></td><td>7 × 8</td></tr><tr><td><strong>Required materials</strong></td><td>Wheat, Corn or Rice</td></tr><tr><td><strong>Production time</strong></td><td>Varies depending on the crop used</td></tr><tr><td><strong>Products produced</strong></td><td>Animal Food</td></tr><tr><td><strong>Selling price</strong></td><td>450 Coins per Animal Food box</td></tr><tr><td><strong>Required equipment</strong></td><td>Suitable vehicle or trailer for transporting Animal Food</td></tr></tbody></table><h2 id="required-materials" tabindex="-1">Required Materials <a class="header-anchor" href="#required-materials" aria-label="Permalink to &quot;Required Materials&quot;">​</a></h2><p>The Animal Food Factory can use three different crops. Each crop produces a different amount of Animal Food.</p><table tabindex="0"><thead><tr><th>Material</th><th style="text-align:right;">Amount Required</th><th style="text-align:right;">Animal Food Produced</th></tr></thead><tbody><tr><td>🌾 Wheat</td><td style="text-align:right;">100</td><td style="text-align:right;">6 boxes</td></tr><tr><td>🌽 Corn</td><td style="text-align:right;">50</td><td style="text-align:right;">12 boxes</td></tr><tr><td>🌾 Rice</td><td style="text-align:right;">10</td><td style="text-align:right;">60 boxes</td></tr></tbody></table><p>Wheat has the shortest crop growth time, while rice takes considerably longer to grow. The factory therefore allows players to choose between smaller, faster production using Wheat and larger production runs using Rice.</p><h2 id="products-produced" tabindex="-1">Products Produced <a class="header-anchor" href="#products-produced" aria-label="Permalink to &quot;Products Produced&quot;">​</a></h2><p>The Animal Food Factory produces <strong>Animal Food boxes</strong>.</p><p>Animal Food can be purchased from AnimalCo for <strong>450 Coins per box</strong>, or produced yourself using the factory. Animal Food is used to keep animals fed and is required for animals to continue producing their respective products.</p><h2 id="production-time" tabindex="-1">Production Time <a class="header-anchor" href="#production-time" aria-label="Permalink to &quot;Production Time&quot;">​</a></h2><p>The factory does not currently have a documented fixed production time.</p><p>Instead, production requires the player to operate a sequence of levers inside the factory. The crop used also affects the overall production cycle because the crops have different growth times.</p><ul><li><strong>Wheat:</strong> 1 minute growth time</li><li><strong>Corn:</strong> 2 minutes 30 seconds growth time</li><li><strong>Rice:</strong> 8 minutes growth time</li></ul><p>These are the crop growth times without growth multipliers, rather than a confirmed factory processing time.</p><h2 id="how-to-use-the-factory" tabindex="-1">How to Use the Factory <a class="header-anchor" href="#how-to-use-the-factory" aria-label="Permalink to &quot;How to Use the Factory&quot;">​</a></h2><h3 id="_1-load-the-factory" tabindex="-1">1. Load the Factory <a class="header-anchor" href="#_1-load-the-factory" aria-label="Permalink to &quot;1. Load the Factory&quot;">​</a></h3><p>Bring the required crop to the side of the Animal Food Factory where the elevated loading platform is located.</p><p>The factory requires at least one complete recipe before production can begin:</p><ul><li><strong>100 Wheat</strong></li><li><strong>50 Corn</strong></li><li><strong>10 Rice</strong></li></ul><p>If the factory does not contain enough ingredients for at least one production cycle, the starting lever will not be available.</p><h3 id="_2-start-production" tabindex="-1">2. Start Production <a class="header-anchor" href="#_2-start-production" aria-label="Permalink to &quot;2. Start Production&quot;">​</a></h3><p>Enter the factory and locate the first lever.</p><p>The lever will display:</p><blockquote><p><strong>Pull Lever to Begin</strong></p></blockquote><p>Pull the lever to start the production process.</p><p>After a short period, the instruction will move to another lever further inside the factory.</p><h3 id="_3-follow-the-levers" tabindex="-1">3. Follow the Levers <a class="header-anchor" href="#_3-follow-the-levers" aria-label="Permalink to &quot;3. Follow the Levers&quot;">​</a></h3><p>Continue moving through the factory and pulling each lever when it becomes available.</p><p>The process requires you to:</p><ol><li>Pull the first lever.</li><li>Wait for the next lever.</li><li>Move to the next lever.</li><li>Pull it.</li><li>Continue following the sequence.</li><li>Repeat until reaching the final lever.</li></ol><p>Once the final stage has been completed, the Animal Food will be produced.</p><h3 id="_4-collect-the-animal-food" tabindex="-1">4. Collect the Animal Food <a class="header-anchor" href="#_4-collect-the-animal-food" aria-label="Permalink to &quot;4. Collect the Animal Food&quot;">​</a></h3><p>The finished Animal Food is loaded from the loading area on the side of the factory.</p><p>If a suitable vehicle or trailer is positioned in the loading area, the Animal Food boxes will automatically be loaded onto it.</p><p>If there is no suitable vehicle or trailer present, the Animal Food will instead appear in the centre of the loading area for manual collection.</p><h2 id="selling-animal-food" tabindex="-1">Selling Animal Food <a class="header-anchor" href="#selling-animal-food" aria-label="Permalink to &quot;Selling Animal Food&quot;">​</a></h2><p>Animal Food can be purchased from AnimalCo for <strong>450 Coins per box</strong>. However, the Animal Food Factory is primarily useful for producing feed for your own animals rather than being a dedicated money-making factory.</p><blockquote><p><strong>Note:</strong> Producing Animal Food yourself may not always be the most profitable use of your crops. Depending on current crop prices, selling the raw crops can provide a better return.</p></blockquote>',40)])])}const m=e(i,[["render",n]]);export{p as __pageData,m as default};
